reply:
```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" .

############################################
## TOP-LEVEL CLASSES
############################################

fis:Asset a owl:Class ;
  rdfs:label "asset" ;
  rdfs:comment "Generic underlying reference: anything a derivative, fund or ABS can be 'based on' or 'backed by' (commodity, financial instrument, index, rate, currency, loan, event)." .

fis:FinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:comment "A monetary contract between parties; can be created, traded, modified and settled (cash, equity, debt or derivative)." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "Instrument whose value is determined directly by the markets (securities, loans, deposits)." .

fis:DerivativeInstrument a owl:Class ;
  rdfs:label "derivative" ;
  rdfs:subClassOf fis:FinancialInstrument ;
  owl:equivalentClass [
    a owl:Class ;
    owl:intersectionOf (
      fis:FinancialInstrument
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Asset ]
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:someValuesFrom xsd:date ]
    )
  ] ;
  rdfs:comment "A contract whose value is derived from an underlier, with a future date by which a buy/sell act must take place (forwards, futures, options, swaps)." .

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "security" , "tradable financial asset" ;
  rdfs:comment "CONFLICT: the US passage lists 'Derivatives' as one of three broad categories of 'security', while other passages treat securities (cash instruments, readily transferable) as distinct from derivatives, and the UK FCA definition includes warrants under 'security'. This ontology follows the majority view that Security is a CashInstrument distinct from DerivativeInstrument, and models warrant-like hybrids (EquityWarrant) as Security/HybridSecurity rather than forcing a contradictory multi-parent under both disjoint branches." .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument .
fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .
fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Loan .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:HomeEquityLoan a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:AutoLoan a owl:Class ; rdfs:subClassOf fis:Loan .
fis:StudentLoan a owl:Class ; rdfs:subClassOf fis:Loan .
fis:CreditCardReceivable a owl:Class ; rdfs:subClassOf fis:Loan .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Index a owl:Class ; rdfs:subClassOf fis:Asset .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Asset .
fis:CreditEvent a owl:Class ; rdfs:subClassOf fis:Asset .

############################################
## ISSUER / INVESTOR
############################################

fis:Issuer a owl:Class ; rdfs:comment "The company or other entity issuing a security." .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Government a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Government .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Government ; rdfs:label "municipality" .
fis:SupranationalOrganisation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Bank a owl:Class ; rdfs:subClassOf fis:Issuer .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:Corporation fis:Government fis:SupranationalOrganisation fis:Bank ) .
[] a owl:AllDisjointClasses ;
  owl:members ( fis:SovereignGovernment fis:LocalGovernment ) .

fis:Investor a owl:Class .
fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor .
fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Investor .
[] a owl:AllDisjointClasses ; owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) .

fis:Shareholder a owl:Class ; rdfs:label "stockholder" ;
  rdfs:subClassOf fis:Investor ;
  owl:equivalentClass [
    owl:intersectionOf ( fis:Investor
      [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:EquitySecurity ] )
  ] .

fis:Bondholder a owl:Class ;
  rdfs:subClassOf fis:Investor ;
  owl:equivalentClass [
    owl:intersectionOf ( fis:Investor
      [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:DebtSecurity ] )
  ] .

############################################
## OBJECT PROPERTIES
############################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Issuer .
fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ; rdfs:domain fis:Issuer ; rdfs:range fis:FinancialInstrument .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Asset .
fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ; rdfs:domain fis:Asset ; rdfs:range fis:FinancialInstrument .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Investor .
fis:isHolderOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolder ; rdfs:domain fis:Investor ; rdfs:range fis:Security .

fis:hasOfferingType a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:SecurityOffering .

############################################
## DATATYPE PROPERTIES
############################################

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:date ;
  rdfs:comment "Date on which issuer repays the nominal amount / contract expires." .

fis:hasCouponRate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal .

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
  rdfs:label "par value" , "principal amount" , "nominal amount" .

fis:hasYield a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasCreditRating a owl:DatatypeProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string .

fis:hasVotingRight a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:EquitySecurity ; rdfs:range xsd:boolean .

fis:hasDividendRate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:PreferredStock ; rdfs:range xsd:decimal .

fis:hasCallFeature a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:hasPutFeature a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:hasCollateral a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:boolean ;
  rdfs:comment "true if the debt security is secured by specific collateral; false if unsecured (debenture)." .

fis:hasOriginalMaturity a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:duration .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasPremium a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasRightToBuy a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:boolean ;
  rdfs:comment "true = call option (right to buy); false = put option (right to sell)." .

fis:hasStandardization a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:boolean ;
  rdfs:comment "true = standardized contract (future); false = non-standardized (forward)." .

fis:hasExchangeTraded a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:boolean .

############################################
## SECURITY OFFERING
############################################

fis:SecurityOffering a owl:Class .
fis:PublicOffering a owl:Class ; rdfs:subClassOf fis:SecurityOffering .
fis:PrivatePlacement a owl:Class ; rdfs:subClassOf fis:SecurityOffering .
[] a owl:AllDisjointClasses ; owl:members ( fis:PublicOffering fis:PrivatePlacement ) .

############################################
## SECURITY STRUCTURAL DIMENSIONS
############################################

fis:CertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security .
fis:NonCertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "book-entry security" , "dematerialized security" .
[] a owl:AllDisjointClasses ; owl:members ( fis:CertificatedSecurity fis:NonCertificatedSecurity ) .

fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:CertificatedSecurity .
fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:CertificatedSecurity .
[] a owl:AllDisjointClasses ; owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) .

fis:DividedSecurity a owl:Class ; rdfs:subClassOf fis:Security .
fis:UndividedSecurity a owl:Class ; rdfs:subClassOf fis:Security .
[] a owl:AllDisjointClasses ; owl:members ( fis:DividedSecurity fis:UndividedSecurity ) .

fis:FungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security .
fis:NonFungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security .
[] a owl:AllDisjointClasses ; owl:members ( fis:FungibleSecurity fis:NonFungibleSecurity ) .

############################################
## DEBT SECURITY / EQUITY SECURITY / HYBRID — TOP SPLIT
############################################

fis:DebtSecurity a owl:Class ;
  rdfs:label "fixed income security" ;
  owl:equivalentClass [
    owl:intersectionOf ( fis:Security
      [ a owl:Restriction ; owl:onProperty fis:hasFaceValue ; owl:someValuesFrom xsd:decimal ]
      [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:someValuesFrom xsd:decimal ]
    )
  ] ;
  rdfs:comment "Holder entitled to payment of principal and interest; generally issued for a fixed term." .

fis:EquitySecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:label "stock" , "share" , "capital stock" ;
  rdfs:comment "A share of equity interest / residual ownership claim in an entity." .

fis:HybridSecurity a owl:Class ;
  rdfs:subClassOf fis:Security ;
  rdfs:comment "Combines characteristics of both debt and equity securities." .

[] a owl:AllDisjointClasses ; owl:members ( fis:DebtSecurity fis:EquitySecurity ) .

############################################
## BOND FAMILY
############################################

fis:Bond a owl:Class ;
  rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Issuer (debtor) owes holder (creditor) a debt; typically repays principal at maturity plus coupon interest. EXCEPTION noted in corpus: irredeemable/perpetual bonds have no maturity date, so Bond is modelled as subClassOf (not strictly equivalent to) DebtSecurity with a maturity requirement." .

[] a owl:AllDisjointClasses ; owl:members ( fis:Bond fis:MoneyMarketInstrument ) .

fis:CorporateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] .

fis:GovernmentBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "treasury bond" , "sovereign bond" ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

fis:MunicipalBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "muni" ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] .

fis:SupranationalBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "supra" ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganisation ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CorporateBond fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond ) .

fis:ZeroCouponBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "discount bond" , "deep discount bond" ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] .

fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "floater" .
[] a owl:AllDisjointClasses ; owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) .

fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "perpetuity" ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:cardinality "0"^^xsd:nonNegativeInteger ] ) ] .

fis:CallableBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCallFeature ; owl:hasValue true ] ) ] .

fis:PutableBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "retractable bond" ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasPutFeature ; owl:hasValue true ] ) ] .

fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ; rdfs:label "straight bond" ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCallFeature ; owl:hasValue false ]
    [ a owl:Restriction ; owl:onProperty fis:hasPutFeature ; owl:hasValue false ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:CallableBond fis:BulletBond ) .
[] a owl:AllDisjointClasses ; owl:members ( fis:PutableBond fis:BulletBond ) .

fis:ConvertibleBond a owl:Class ; rdfs:subClassOf fis:Bond , fis:HybridSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] .

fis:BearerBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] .

fis:RegisteredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] .

fis:BookEntryBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:NonCertificatedSecurity ) ] .

fis:SeniorBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:SubordinatedBond a owl:Class ; rdfs:subClassOf fis:Bond .
[] a owl:AllDisjointClasses ; owl:members ( fis:SeniorBond fis:SubordinatedBond ) .

fis:Debenture a owl:Class ; rdfs:subClassOf fis:Bond ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:hasValue false ] ) ] ;
  rdfs:comment "CONFLICT: one passage uses 'debenture' generically for any debt security classified by maturity, while another defines debenture specifically as an unsecured bond. This ontology follows the more specific (FINRA-aligned) definition: unsecured bond." .

fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ; rdfs:label "junk bond" .
fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:CorporateBond ; rdfs:label "high grade bond" .
[] a owl:AllDisjointClasses ; owl:members ( fis:HighYieldBond fis:InvestmentGradeBond ) .

############################################
## MONEY MARKET INSTRUMENTS
############################################

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:DebtSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasOriginalMaturity ;
      owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:duration ;
        owl:withRestrictions ( [ xsd:maxInclusive "P1Y"^^xsd:duration ] ) ] ] ) ] .

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  owl:equivalentClass [ owl:intersectionOf ( fis:MoneyMarketInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasOriginalMaturity ;
      owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:duration ;
        owl:withRestrictions ( [ xsd:maxInclusive "P270D"^^xsd:duration ] ) ] ]
    [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:hasValue false ] ) ] ;
  rdfs:comment "Unsecured promissory note, usually maturing in less than 270 days." .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ; rdfs:label "CD" ;
  rdfs:comment "Time deposit; retail CDs are typically non-transferable, while 'jumbo' CDs are negotiable bearer-form securities." .

fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  owl:equivalentClass [ owl:intersectionOf ( fis:MoneyMarketInstrument
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:CommercialPaper fis:CertificateOfDeposit fis:TreasuryBill ) .

############################################
## ASSET-BACKED / MORTGAGE-BACKED FAMILY
############################################

fis:AssetBackedSecurity a owl:Class ; rdfs:label "ABS" ; rdfs:subClassOf fis:DebtSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:DebtSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Loan ] ) ] ;
  rdfs:comment "Umbrella term for a security backed by a pool of assets; sometimes used narrowly for consumer-loan-backed securities distinct from MBS/CDO." .

fis:MortgageBackedSecurity a owl:Class ; rdfs:label "MBS" ; rdfs:subClassOf fis:AssetBackedSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Mortgage ] ) ] .

fis:CollateralizedDebtObligation a owl:Class ; rdfs:label "CDO" ; rdfs:subClassOf fis:AssetBackedSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtSecurity ] ) ] .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:label "CMO" , "pay-through bond" ; rdfs:subClassOf fis:MortgageBackedSecurity .
fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:label "SMBS" ; rdfs:subClassOf fis:MortgageBackedSecurity .
fis:InterestOnlyStrip a owl:Class ; rdfs:label "IO strip" ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:label "PO strip" ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:PassThroughSecurity fis:CollateralizedMortgageObligation fis:StrippedMortgageBackedSecurity ) .
[] a owl:AllDisjointClasses ; owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) .

fis:ResidentialMortgageBackedSecurity a owl:Class ; rdfs:label "RMBS" ; rdfs:subClassOf fis:PassThroughSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:PassThroughSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .

fis:CommercialMortgageBackedSecurity a owl:Class ; rdfs:label "CMBS" ; rdfs:subClassOf fis:PassThroughSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:PassThroughSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) .

fis:AutoLoanBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:AutoLoan ] ) ] .

fis:CreditCardBackedSecurity a owl:Class ; rdfs:subClassOf fis:AssetBackedSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CreditCardReceivable ] ) ] .

fis:StudentLoanBackedSecurity a owl:Class ; rdfs:label "SLABS" ; rdfs:subClassOf fis:AssetBackedSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:StudentLoan ] ) ] .

fis:HomeEquityLoanBackedSecurity a owl:Class ; rdfs:label "HEL ABS" ; rdfs:subClassOf fis:AssetBackedSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:HomeEquityLoan ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:AutoLoanBackedSecurity fis:CreditCardBackedSecurity
                fis:StudentLoanBackedSecurity fis:HomeEquityLoanBackedSecurity
                fis:MortgageBackedSecurity fis:CollateralizedDebtObligation ) .

############################################
## EQUITY FAMILY
############################################

fis:CommonStock a owl:Class ; rdfs:label "ordinary share" , "voting share" ; rdfs:subClassOf fis:EquitySecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:EquitySecurity
    [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue true ] ) ] .

fis:PreferredStock a owl:Class ; rdfs:label "preference share" ; rdfs:subClassOf fis:EquitySecurity , fis:HybridSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:EquitySecurity fis:HybridSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue false ] ) ] ;
  rdfs:comment "Most preferred shares carry no voting right, though some gain special or full voting rights under certain conditions (e.g. cumulative dividends in arrears)." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CommonStock fis:PreferredStock ) .

fis:ConvertiblePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  owl:equivalentClass [ owl:intersectionOf ( fis:PreferredStock
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] .

############################################
## HYBRID — WARRANTS / DEPOSITARY RECEIPTS
############################################

fis:EquityWarrant a owl:Class ; rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [ owl:intersectionOf ( fis:HybridSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ]
    [ a owl:Restriction ; owl:onProperty fis:hasStrikePrice ; owl:someValuesFrom xsd:decimal ]
  ) ] ;
  rdfs:comment "Option-like instrument issued by a company allowing purchase of a specified number of shares at a specified price within a specified time." .

fis:DepositaryReceipt a owl:Class ; rdfs:label "DR" ; rdfs:subClassOf fis:Security ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Bank ]
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
  ) ] .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:label "ADR" ; rdfs:subClassOf fis:DepositaryReceipt .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:label "EDR" ; rdfs:subClassOf fis:DepositaryReceipt .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:label "GDR" ; rdfs:subClassOf fis:DepositaryReceipt .
[] a owl:AllDisjointClasses ;
